import {
  createRootRoute,
  createRoute,
  createRouter,
  Outlet,
  RouterProvider,
  useNavigate,
  createMemoryHistory,
} from '@tanstack/react-router';

export const rootRoute = createRootRoute({ component: () => <Outlet /> });

export function HomeView() {
  const navigate = useNavigate();
  return <button onClick={() => navigate({ to: '/about' })}>go</button>;
}

export const homeRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/',
  component: HomeView,
});

export const aboutRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/about',
  component: () => <p>about</p>,
});

const routeTree = rootRoute.addChildren([homeRoute, aboutRoute]);

export function makeRouter(initialEntries: string[] = ['/']) {
  return createRouter({
    routeTree,
    history: createMemoryHistory({ initialEntries }),
  });
}

export function App({ initialEntries }: { initialEntries?: string[] }) {
  return <RouterProvider router={makeRouter(initialEntries)} />;
}
